css:
@import url("https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700;800&family=Barlow:wght@400;500;600;700&display=swap");
:root{--navy:#0B1F3A;--navy-2:#15325A;--red:#E23D3D;--red-d:#C22A2A;--steel:#EEF1F4;--steel-2:#DDE3EA;--green:#1E9E64;--amber:#E0A21B;--text:#1D2B3E;--muted:#5A687A;--line:#D3DAE3;
--display:"Barlow Condensed","Arial Narrow",sans-serif;--body:"Barlow",system-ui,-apple-system,"Segoe UI",sans-serif;--wrap:1220px}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;font-family:var(--body);font-size:18px;line-height:1.6;color:var(--text);background:#fff;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}a{color:inherit}p{margin:0 0 1em}
h1,h2,h3{font-family:var(--display);font-weight:800;margin:0;line-height:1;color:var(--navy);text-transform:uppercase;letter-spacing:.005em}h3{font-weight:700}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 24px}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--red);color:#fff;padding:10px;z-index:99}
:focus-visible{outline:3px solid var(--red);outline-offset:3px}
.alert{background:var(--red);color:#fff;font-weight:600;font-size:16px}
.alert .wrap{display:flex;justify-content:center;gap:12px;padding-top:8px;padding-bottom:8px;flex-wrap:wrap}
.alert a{font-weight:700}
.site-header{position:sticky;top:0;z-index:40;background:var(--navy);color:#fff}
.nav{display:flex;align-items:center;justify-content:space-between;height:74px}
.logo{display:flex;align-items:center;gap:10px;font-family:var(--display);font-weight:800;font-size:28px;text-decoration:none;color:#fff;letter-spacing:.04em}
.logo svg{width:30px;height:30px}
.menu{display:flex;gap:28px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none;font-weight:600;color:#C4CFDD}.menu a:hover{color:#fff}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:14px 26px;font-weight:700;text-decoration:none;border:2px solid transparent;font-family:var(--body);font-size:17px;cursor:pointer;border-radius:4px}
.btn-red{background:var(--red);color:#fff}.btn-red:hover{background:var(--red-d)}
.btn-white{background:#fff;color:var(--navy)}.btn-line{border-color:#fff;color:#fff}.btn-navy{background:var(--navy);color:#fff}
.burger{display:none;background:none;border:2px solid #fff;border-radius:4px;padding:8px 10px;cursor:pointer}.burger span{display:block;width:20px;height:2px;background:#fff;margin:4px 0}
.hero{position:relative;background:var(--navy);color:#C4CFDD;overflow:hidden}
.hero img.bg{position:absolute;right:0;top:0;width:55%;height:100%;object-fit:cover;opacity:.55;mask-image:linear-gradient(90deg,transparent,#000 40%);-webkit-mask-image:linear-gradient(90deg,transparent,#000 40%)}
.hero .wrap{position:relative;padding-top:100px;padding-bottom:110px}
.hero h1{color:#fff;font-size:clamp(52px,7.6vw,110px);max-width:12ch}
.hero h1 span{color:var(--red)}
.hero .lead{font-size:21px;max-width:46ch;margin:24px 0 32px;color:#D5DEE9}
.actions{display:flex;gap:12px;flex-wrap:wrap}
.certs{display:flex;gap:12px;flex-wrap:wrap;margin-top:40px}
.certs span{border:1px solid #2F4B72;border-radius:4px;padding:6px 14px;font-weight:600;font-size:15px;color:#fff}
.threat{background:var(--steel);border-bottom:1px solid var(--line)}
.threat .wrap{display:grid;grid-template-columns:repeat(4,1fr)}
.threat div{padding:34px 24px;border-right:1px solid var(--line)}.threat div:last-child{border-right:0}
.threat b{font-family:var(--display);font-size:52px;color:var(--red);display:block;line-height:1}
.threat span{font-size:16px;color:var(--muted)}
section{padding:110px 0}
.head{max-width:760px;margin-bottom:50px}.head h2{font-size:clamp(40px,5.4vw,72px)}.head p{color:var(--muted);font-size:19px;margin-top:14px}
.tag{font-weight:700;color:var(--red);font-size:15px;display:block;margin-bottom:12px}
.svc{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.card{border:1px solid var(--line);border-top:4px solid var(--navy);padding:30px;background:#fff}
.card:hover{border-top-color:var(--red)}
.card h3{font-size:30px;margin-bottom:10px}.card p{margin:0 0 12px;color:var(--muted);font-size:17px}
.card ul{padding-left:18px;margin:0;font-size:16px}
.check{background:var(--navy);color:#C4CFDD}
.check h2{color:#fff}.check .head p{color:#9FB0C6}
.check-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:50px;align-items:start}
.qs{display:grid;gap:10px}
.qs label{display:flex;gap:14px;align-items:center;background:var(--navy-2);border:1px solid #2F4B72;border-radius:6px;padding:16px 18px;cursor:pointer;font-weight:600;color:#fff}
.qs input{width:22px;height:22px;accent-color:var(--green);flex:none}
.score{background:#fff;color:var(--text);border-radius:8px;padding:30px;position:sticky;top:100px}
.score .num{font-family:var(--display);font-size:92px;font-weight:800;line-height:1;color:var(--red)}
.score .num small{font-size:36px;color:var(--muted)}
.meter{height:12px;background:var(--steel-2);border-radius:6px;margin:14px 0 18px;overflow:hidden}.meter i{display:block;height:100%;width:0;background:var(--red);transition:width .4s,background .4s}
.score h3{font-size:30px;margin-bottom:8px}.score p{color:var(--muted);font-size:17px}
.resp{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}
.resp img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:6px}
.timeline{list-style:none;padding:0;margin:0;border-left:3px solid var(--line)}
.timeline li{position:relative;padding:0 0 24px 26px}
.timeline li::before{content:"";position:absolute;left:-9px;top:4px;width:15px;height:15px;border-radius:50%;background:var(--red);border:3px solid #fff;box-shadow:0 0 0 2px var(--red)}
.timeline b{font-family:var(--display);font-size:24px;color:var(--navy);text-transform:uppercase;display:block}
.timeline span{color:var(--muted);font-size:17px}
.packs{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.pack{border:1px solid var(--line);padding:32px;display:flex;flex-direction:column;background:#fff}
.pack.hot{border:2px solid var(--navy);background:var(--steel)}
.pack h3{font-size:32px}.pack .amt{font-family:var(--display);font-size:50px;font-weight:800;color:var(--navy);margin:10px 0 0}
.pack .amt small{font-family:var(--body);font-size:16px;font-weight:500;color:var(--muted)}
.pack ul{list-style:none;padding:0;margin:18px 0 26px;font-size:16px}.pack li{padding:8px 0 8px 28px;position:relative;border-bottom:1px solid var(--line)}
.pack li::before{content:"";position:absolute;left:2px;top:14px;width:12px;height:12px;background:var(--green);clip-path:polygon(14% 44%,0 65%,50% 100%,100% 16%,80% 0,43% 62%)}
.pack .btn{margin-top:auto}
.case{background:var(--steel)}
.case-box{display:grid;grid-template-columns:1fr 1fr;gap:50px;align-items:center}
.case-box blockquote{margin:0}.case-box blockquote p{font-size:clamp(22px,2.6vw,30px);font-weight:600;color:var(--navy);line-height:1.35}
.case-box cite{font-style:normal;color:var(--muted)}
.kpis{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.kpis div{background:#fff;padding:24px;border-left:4px solid var(--red)}
.kpis b{font-family:var(--display);font-size:46px;color:var(--navy);display:block;line-height:1}.kpis span{font-size:16px;color:var(--muted)}
.faq{max-width:840px}
.faq details{border-bottom:1px solid var(--line);padding:20px 0}
.faq summary{list-style:none;cursor:pointer;font-weight:700;font-size:20px;display:flex;justify-content:space-between;gap:18px;color:var(--navy)}
.faq summary::-webkit-details-marker{display:none}.faq summary::after{content:"+";font-size:26px;line-height:1;color:var(--red)}
.faq details[open] summary::after{content:"−"}.faq details p{margin:10px 0 0;color:var(--muted)}
.contact{background:var(--navy);color:#C4CFDD}
.contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:50px;align-items:start}
.contact h2{color:#fff;font-size:clamp(40px,5vw,68px)}
.hotline{background:var(--red);color:#fff;border-radius:6px;padding:24px;margin-top:26px}
.hotline b{font-family:var(--display);font-size:40px;display:block;line-height:1.1}
form{background:#fff;border-radius:6px;padding:30px;color:var(--text)}
label{display:block;font-weight:700;font-size:15px;margin-bottom:6px;color:var(--navy)}
input,select,textarea{width:100%;font:inherit;font-size:17px;padding:12px 14px;border:1px solid var(--line);border-radius:4px;margin-bottom:16px;color:var(--text);background:#fff}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--navy)}
form .btn{width:100%}
footer{background:#07152A;color:#8FA1B8;padding:40px 0;font-size:15px}
.foot{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;align-items:center}
footer ul{list-style:none;padding:0;margin:0;display:flex;gap:22px;flex-wrap:wrap}footer a{text-decoration:none}footer a:hover{color:#fff}
@media (max-width:1000px){.menu,.nav>.btn{display:none}.burger{display:block}
.menu.open{display:flex;flex-direction:column;position:absolute;top:74px;left:0;right:0;background:var(--navy);padding:22px 24px;gap:16px}
.hero img.bg{width:100%;opacity:.25;mask-image:none;-webkit-mask-image:none}
.threat .wrap{grid-template-columns:1fr 1fr}.threat div:nth-child(2){border-right:0}
.svc,.packs{grid-template-columns:1fr 1fr}.check-grid,.resp,.case-box,.contact-grid{grid-template-columns:1fr}.score{position:static}}
@media (max-width:600px){body{font-size:17px}section{padding:76px 0}.svc,.packs,.threat .wrap,.kpis{grid-template-columns:1fr}.threat div{border-right:0;border-bottom:1px solid var(--line)}}

javascript:
const boxes=[...document.querySelectorAll('#qs input')];
const msgs=[["High risk","Most attacks on businesses like yours use gaps you can close in a week. Book a free review and we'll show you where to start.","#E23D3D"],["Some risk","You have good basics, but a few gaps attackers look for. A review will show which ones to fix first.","#E0A21B"],["Well protected","Great work. A yearly review and penetration test will keep it that way as you grow.","#1E9E64"]];
function upd(){const n=boxes.filter(b=>b.checked).length,m=n<3?msgs[0]:n<6?msgs[1]:msgs[2];
document.getElementById('sc').textContent=n;const mt=document.getElementById('mt');mt.style.width=(n/6*100)+'%';mt.style.background=m[2];
document.getElementById('sh').textContent=m[0];document.getElementById('sp').textContent=m[1];document.getElementById('sc').parentElement.style.color=m[2]}
boxes.forEach(b=>b.addEventListener('change',upd));
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
